#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
WORK_DIR="$(mktemp -d)"

cleanup() {
    rm -rf "${WORK_DIR}"
}

trap cleanup EXIT

command -v kubectl >/dev/null 2>&1 || {
    echo "kubectl is required for the post-renderer" >&2
    exit 1
}

# Capture the manifests generated by Helm.
cat > "${WORK_DIR}/helm-output.yaml"

# Verify that the expected Deployment is present.
if ! grep -q 'name: forgejo-runner-forge-runner' \
    "${WORK_DIR}/helm-output.yaml"; then
    echo "Expected Forgejo Runner Deployment was not found" >&2
    exit 1
fi

# Copy the version-controlled patches.
cp "${SCRIPT_DIR}/buildkit-apparmor.yaml" "${WORK_DIR}/"
cp "${SCRIPT_DIR}/runner-ca.yaml" "${WORK_DIR}/"

# Build the Kustomize configuration.
cat > "${WORK_DIR}/kustomization.yaml" <<'EOF'
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization

resources:
  - helm-output.yaml

patches:
  - path: buildkit-apparmor.yaml
  - path: runner-ca.yaml
EOF

# Render into a temporary file to avoid partial output on failure.
kubectl kustomize "${WORK_DIR}" > "${WORK_DIR}/rendered.yaml"

# Validate the expected changes before returning anything to Helm.
if ! grep -q 'appArmorProfile:' "${WORK_DIR}/rendered.yaml"; then
    echo "BuildKit AppArmor patch was not applied" >&2
    exit 1
fi

if ! grep -q 'name: homelab-root-ca' "${WORK_DIR}/rendered.yaml"; then
    echo "Runner CA patch was not applied" >&2
    exit 1
fi

cat "${WORK_DIR}/rendered.yaml"